section.para:
This module provides a high-performance connector to interact with
Tarantool 3.x in-memory database from &kamailio;
routing scripts, C modules, and KEMI engines over the binary IProto protocol.

section.programlisting:
#!KAMAILIO

loadmodule "tm.so"
loadmodule "sl.so"
loadmodule "rr.so"
loadmodule "pv.so"
loadmodule "rtpengine.so"
loadmodule "ndb_tarantool.so"

# Configure Tarantool connector
modparam("ndb_tarantool", "server", "srv1=127.0.0.1:3301")
modparam("ndb_tarantool", "pool_size", 8)
modparam("ndb_tarantool", "connect_timeout", 500)
modparam("ndb_tarantool", "cmd_timeout", 500)
modparam("ndb_tarantool", "init_without_tarantool", 1)

# Default fallback RTPEngine socket
modparam("rtpengine", "rtpengine_sock", "udp:127.0.0.1:22222")

route {
    if (is_method("INVITE")) {
        record_route();

        # 1. Query Tarantool for optimal least-loaded media node (70 µs)
        if (tnt_call("srv1", "select_optimal_node", "$ci", "$var(node)")) {
            xlog("L_INFO", "Routing Call-ID: $ci via optimal media node: $var(node)\n");
            $var(rtpe_sock) = "udp:" + $var(node) + ":22222";
            $rtpengine_sock = $var(rtpe_sock);
        }

        # 2. Engage RTPEngine media proxy
        rtpengine_offer("replace-origin replace-session-connection");

        t_on_reply("MANAGE_REPLY");
        t_relay();
        exit;
    }

    if (is_method("BYE|CANCEL")) {
        rtpengine_delete();
        t_relay();
        exit;
    }

    t_relay();
}

onreply_route[MANAGE_REPLY] {
    if (status =~ "[12][0-9][0-9]") {
        rtpengine_answer("replace-origin replace-session-connection");
    }
}
